  const DICT = { en, fr, pt, ar };
  const fill = (s, v) => String(s).replace(/\{(\w+)\}/g, (_, k) => (v && v[k] != null ? v[k] : ""));
  let lang = "en";
  try { lang = localStorage.getItem("lara_lang") || ""; } catch {}
  if (!DICT[lang]) {
    const nav = (navigator.language || "en").slice(0, 2);
    lang = DICT[nav] ? nav : "en";
  }

  const api = {
    get lang() { return lang; },
    t(key, vars) { const d = DICT[lang] || en; return fill(d[key] != null ? d[key] : en[key] != null ? en[key] : key, vars); },
    tl(l, key, vars) {
      const x = (window.LARA_LETTERS || {})[l] || {};
      const d = DICT[l] || {};
      const v = x[key] != null ? x[key] : d[key] != null ? d[key] : en[key] != null ? en[key] : key;
      return fill(v, vars);
    },
    apply(root) {
      document.documentElement.lang = lang;
      document.documentElement.dir = lang === "ar" ? "rtl" : "ltr";
      (root || document).querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = api.t(el.dataset.i18n); });
      (root || document).querySelectorAll("[data-i18n-html]").forEach((el) => { el.innerHTML = api.t(el.dataset.i18nHtml); });
      (root || document).querySelectorAll("[data-i18n-ph]").forEach((el) => { el.placeholder = api.t(el.dataset.i18nPh); });
    },
    setLang(l) {
      if (!DICT[l]) return;
      lang = l;
      try { localStorage.setItem("lara_lang", l); } catch {}
      api.apply(document);
      document.dispatchEvent(new CustomEvent("lara:lang"));
    },
  };
  window.LARA_I18N = api;
